// Ported from the Node app's Sequelize model Payment (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class PaymentConfiguration : IEntityTypeConfiguration<Payment>
{
    public void Configure(EntityTypeBuilder<Payment> builder)
    {
        builder.ToTable("payments", t =>
        {
            t.HasCheckConstraint("CK_payments_method", "[method] IN (N'cash', N'card', N'upi', N'bank')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.FeeId).HasColumnName("fee_id");
        builder.Property(e => e.Amount).HasColumnName("amount").HasColumnType("decimal(10,2)");
        builder.Property(e => e.Method).HasColumnName("method").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'cash'");
        builder.Property(e => e.ReceiptNo).HasColumnName("receipt_no").HasColumnType("nvarchar(30)").HasMaxLength(30).IsRequired();
        builder.Property(e => e.PaidOn).HasColumnName("paid_on").HasColumnType("date");
        builder.Property(e => e.ReceivedBy).HasColumnName("received_by");
        builder.HasIndex(e => e.ReceiptNo).IsUnique();
        builder.HasOne(e => e.Fee).WithMany(p => p.Payments).HasForeignKey(e => e.FeeId).OnDelete(DeleteBehavior.NoAction);
    }
}
